/* n8n hands an error workflow the failing execution, not our data. So the
   month and runId have to be recovered, in this order:

     1. execution.customData — the Orchestrator sets month and runId there for
        exactly this reason (step 3 wires it: $execution.customData.set(...)).
     2. $vars.RBL_MONTH — set only when re-running a specific month.
     3. last month — the same default the Orchestrator resolves to.

   If runId cannot be found, the release below runs WITHOUT --run-id, which
   makes lock.mjs refuse to release a live foreign lock. That is the correct
   outcome: releasing a lock we cannot prove is ours would leave two writers on
   one month. The notification then says the lock is still held, which is a
   thing a human can act on. */

const e = $input.first().json;
const execution = e.execution ?? {};
const workflow = e.workflow ?? {};
const custom = execution.customData ?? {};

const lastMonth = () => {
  const d = new Date();
  d.setDate(1);
  d.setMonth(d.getMonth() - 1);
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
};

const month = String(custom.month || $vars.RBL_MONTH || lastMonth()).trim();
const runId = String(custom.runId || '').trim();
const stage = String(custom.stage || '').trim();

const err = execution.error ?? {};
const node = err.node?.name || execution.lastNodeExecuted || '(unknown node)';
const message = String(err.message || 'no message');
/* The tail, not the head: the useful part of a stack or a stderr dump is the
   end. Capped so a runaway log cannot fill a Slack message. */
const detail = String(err.stack || err.description || '').slice(-2000);

const crash = JSON.stringify({ node, message, stage, runId, executionUrl: execution.url || '', stderrTail: detail });

const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const repo = $vars.RBL_REPO;
if (!repo) throw new Error('n8n variable RBL_REPO is not set — the Error Handler cannot release the lock');

const command = 'cd ' + q(repo)
  + ' && npm run pipeline --silent -- --stage lock --month ' + q(month)
  + ' --release'
  + (runId ? ' --run-id ' + q(runId) : '')
  + ' --crash ' + q(crash)
  + ' --json';

return [{
  json: {
    month, runId, stage, node, message, detail,
    workflowName: workflow.name || '(unknown workflow)',
    executionId: execution.id || '',
    executionUrl: execution.url || '',
    monthSource: custom.month ? 'execution.customData' : ($vars.RBL_MONTH ? '$vars.RBL_MONTH' : 'computed as last month'),
    command,
  },
}];

/* Did the lock actually come off? This is the question the next scheduled run
   depends on: a crash that leaves the lock held wedges it, and the failure a
   month later points at a process that died in October. */
const meta = $('Extract the failure').first().json;
const out = $('Release the lock').first().json;

/* THE SENTINEL IS THE ONLY RELIABLE EXIT CODE. Measured on n8n 2.35.7: the
   Execute Command node reports `exitCode` only when the command exits 0. On any
   non-zero exit it emits `{ error }` alone — no exitCode, no stdout — so a
   lock.mjs exit 10 ("someone else holds this month", a decision) is
   indistinguishable from a crash. The command is wrapped to always exit 0 and
   print __EXIT__<code> on stdout. */
const stdoutRaw = String(out.stdout ?? '');
const sentinelMatch = [...stdoutRaw.matchAll(/^__EXIT__(\d+)\s*$/gm)].pop();
const exitCode = sentinelMatch ? Number(sentinelMatch[1])
  : (Number.isFinite(Number(out.exitCode)) ? Number(out.exitCode) : (out.error ? 1 : 0));
const stdout = stdoutRaw.replace(/^__EXIT__\d+\s*$/gm, '');
const line = stdout.split('\n').map((l) => l.trim()).filter((l) => l.startsWith('{')).pop();
let res = null;
try { res = line ? JSON.parse(line) : null; } catch (err) { res = null; }

const released = res?.released === true;
const nothingHeld = res?.released === false && /no lock was held/i.test(res?.reason ?? '');
const lockNote = released
  ? 'Month lock released.'
  : nothingHeld
    ? 'No month lock was held.'
    : 'MONTH LOCK NOT RELEASED (exit ' + exitCode + ') — ' + (res?.reason ?? 'the release command produced no parseable result') +
      '\nThe next scheduled run for ' + meta.month + ' will refuse to start until this is cleared:' +
      '\n  npm run pipeline -- --stage lock --month ' + meta.month + ' --status';

const body = [
  meta.workflowName + ' failed at "' + meta.node + '".',
  '',
  meta.message,
  '',
  lockNote,
  '',
  'Month resolved from: ' + meta.monthSource,
  meta.runId ? '' : 'No runId was recoverable from the failed execution — see the Orchestrator note about execution.customData.',
  '',
  meta.detail ? '--- tail ---' : '',
  meta.detail,
].filter((l) => l !== '').join('\n');

return [{
  json: {
    severity: 'fail',
    runId: meta.runId || '(no runId)',
    month: meta.month,
    stage: meta.stage,
    title: 'crash in ' + meta.workflowName,
    body,
    executionUrl: meta.executionUrl,
    resumeUrl: '',
    attachments: '',
    lockReleased: released,
    lockResult: res,
  },
}];
